#include "sblr_sec_drop_policy_runtime.hpp"
#include <cstring>
namespace scratchbird::engine::sblr { namespace { void w16(std::vector<uint8_t>&b,size_t o,uint16_t v){b[o]=v;b[o+1]=v>>8;} void w32(std::vector<uint8_t>&b,size_t o,uint32_t v){for(int i=0;i<4;i++)b[o+i]=v>>(8*i);} void w64(std::vector<uint8_t>&b,size_t o,uint64_t v){for(int i=0;i<8;i++)b[o+i]=v>>(8*i);} uint64_t r64(const uint8_t*p,size_t o){uint64_t v=0;for(int i=0;i<8;i++)v|=uint64_t(p[o+i])<<(8*i);return v;} void cp(std::vector<uint8_t>&b,size_t o,const void*p,size_t n){std::memcpy(b.data()+o,p,n);} bool head(const uint8_t*p,size_t n,const char*m,size_t z,std::string*d){if(!p||n!=z||std::memcmp(p,m,4)||p[4]!=1||(uint16_t(p[6])|(uint16_t(p[7])<<8))!=z||uint32_t(p[8])|(uint32_t(p[9])<<8)|(uint32_t(p[10])<<16)|(uint32_t(p[11])<<24)!=z){if(d)*d="SDP fixed-size header invalid";return false;}return true;}}
std::vector<uint8_t> EncodeSblrSecDropPolicyRequestV1(const SblrSecDropPolicyRequestV1&v){std::vector<uint8_t>b(64);cp(b,0,"SDPQ",4);w16(b,4,1);w16(b,6,64);w32(b,8,64);cp(b,16,v.receipt.data(),16);w64(b,32,v.occurrence);return b;} bool DecodeSblrSecDropPolicyRequestV1(const uint8_t*p,size_t n,SblrSecDropPolicyRequestV1*o,std::string*d){if(!head(p,n,"SDPQ",64,d))return false;std::memcpy(o->receipt.data(),p+16,16);o->occurrence=r64(p,32);return o->occurrence!=0;}
std::vector<uint8_t> EncodeSblrSecDropPolicyDescriptorV1(const SblrSecDropPolicyDescriptorV1&v,bool op){std::vector<uint8_t>b(128);cp(b,0,op?"SDPO":"SDPD",4);w16(b,4,1);w16(b,6,128);w32(b,8,128);cp(b,16,v.policy_uuid.data(),16);w64(b,32,v.expected_generation);w64(b,40,v.catalog_generation);w64(b,48,v.security_generation);w64(b,56,v.availability);cp(b,64,v.descriptor_evidence.data(),16);return b;} bool DecodeSblrSecDropPolicyDescriptorV1(const uint8_t*p,size_t n,SblrSecDropPolicyDescriptorV1*o,std::string*d,bool op){if(!head(p,n,op?"SDPO":"SDPD",128,d))return false;std::memcpy(o->policy_uuid.data(),p+16,16);o->expected_generation=r64(p,32);o->catalog_generation=r64(p,40);o->security_generation=r64(p,48);o->availability=r64(p,56);std::memcpy(o->descriptor_evidence.data(),p+64,16);return o->availability!=0;}
std::vector<uint8_t> EncodeSblrSecDropPolicyResultV1(const SblrSecDropPolicyResultV1&v){std::vector<uint8_t>b(128);cp(b,0,"SDPR",4);w16(b,4,1);w16(b,6,128);w32(b,8,128);b[16]=v.status;b[17]=v.publication_barrier;cp(b,24,v.policy_uuid.data(),16);w64(b,40,v.generation);w64(b,48,v.security_generation);w64(b,56,v.availability);cp(b,64,v.effect_evidence.data(),32);return b;} bool DecodeSblrSecDropPolicyResultV1(const uint8_t*p,size_t n,SblrSecDropPolicyResultV1*o,std::string*d){if(!head(p,n,"SDPR",128,d))return false;o->status=p[16];o->publication_barrier=p[17];std::memcpy(o->policy_uuid.data(),p+24,16);o->generation=r64(p,40);o->security_generation=r64(p,48);o->availability=r64(p,56);std::memcpy(o->effect_evidence.data(),p+64,32);return true;}}
